// INSERT STATEMENTS
async function insert_iteratively(opts) {
    console.log("=========== .  @ inserting iteratively .===============")
    try {
        this.typeql_schema_dict = opts.geminos_schema_dict;
        for await (let key of opts.types) {
            if (this.typeql_schema_dict[key].length > 0) {
                await commit_section(key, opts.split_type);
            }
        }
    } catch (exception) {
        console.log(exception);
        throw exception;
    }
}

async function deploy_instances(req, res) {
    try {
        database = req.body.database;
        await create_session("DATA");
        await create_transaction("WRITE");
        await insert_iteratively(req.body);
        if (transaction.isOpen()) {
            console.log("\tclosing transaction");
            await close_transaction("WRITE");
        }
        if (session.isOpen()) {
            console.log("\tclosing session");
            await session.close();
        }
        res.send("added iteratively");
    } catch (exception) {
        console.log(exception);
        res.send(exception);
        throw exception
    };
};


