/**
 * Creates insert statement for causal analysis attributes in geminos meta schema
 * @param {*} attributes 
 * @param {*} statement 
 * @param {*} library 
 * @returns 
 */
async function create_causal_analysis_instance(attributes, statement, library) {
    statement += "$causal_analysis has ca_uuid \"" + attributes.ca_uuid + "\", has ca_timestamp \"" + attributes.ca_timestamp + "\", has ca_library \"" + library + "\"";
    if (library === "dowhy") {
        Object.keys(attributes.result["dowhy"]).forEach(
            (key) => {
                Object.keys(attributes.result["dowhy"][key]).forEach(
                    (subkey) => {
                        let attribute_result = attributes.result["dowhy"][key][subkey]
                        if (typeof (attribute_result) === "string") {
                            attribute_result = attribute_result.replace(/"/g, "");
                        }
                        statement += ", has " + dowhy_attribute_map[subkey] + " \"" + attribute_result + "\"";
                    }
                );
            }
        );
        statement += ", has " + dowhy_attribute_map["estimation_method"] + " \"" + attributes["estimation_method"] + "\"";

    } else if (library === "causalml") {
        console.log(Object.keys(attributes.result["causalml"]));
        Object.keys(attributes.result[library]).forEach(
            (key) => {
                let attribute_result = attributes.result[library][key];
                if (typeof (attribute_result) === "string") {
                    attribute_result = attribute_result.replace(/"/g, "");
                }
                if (causalml_attribute_map[key] !== undefined) {
                    statement += ", has " + causalml_attribute_map[key] + " \"" + attribute_result + "\"";
                }
            }
        )
        statement += ", has " + causalml_attribute_map["category"] + " \"" + attributes["category"] + "\"";
        statement += ", has " + causalml_attribute_map["estimation_type"] + " \"" + attributes["estimation_type"] + "\"";
        statement += ", has " + causalml_attribute_map["estimator_type"] + " \"" + attributes["estimator_type"] + "\"";
    } else if (library === "econml") {
        console.log(Object.keys(attributes.result[library]));
        Object.keys(attributes.result[library]).forEach(
            (key) => {
                let attribute_result = attributes.result[library][key];

                if (typeof (attribute_result) === "string") {
                    attribute_result = attribute_result.replace(/"/g, "");
                }
                if (econml_attribute_map[key] !== undefined) {
                    statement += ", has " + econml_attribute_map[key] + " \"" + attribute_result + "\"";
                }
            }
        )
        statement += ", has " + econml_attribute_map["category"] + " \"" + attributes["category"] + "\"";
        statement += ", has " + econml_attribute_map["estimation_type"] + " \"" + attributes["estimation_type"] + "\"";
        statement += ", has " + econml_attribute_map["estimator_type"] + " \"" + attributes["estimator_type"] + "\"";
    };
    return Promise.resolve(statement)
}


async function create_meta_causal_analysis(attributes, index) {
    console.log("create_causal_analysis_instance")

    let { ca_treatment_name, ca_treatment_id } = attributes.treatment;
    let { ca_outcome_name, ca_outcome_id } = attributes.outcome;
    let { cm_name, cm_id } = attributes.causal_model;
    let ca_results = attributes.result;
    let ca_library = attributes.libraries[index];
    let ca_insert_statement = "match\n";
    ca_insert_statement += "$treatment isa causeeffect, has name \"" + ca_treatment_name + "_" + cm_id + "\";\n";
    ca_insert_statement += "$outcome isa causeeffect, has name \"" + ca_outcome_name + "_" + cm_id + "\";\n";
    return ca_insert_statement
}

async function inject_causal_analysis_instance(attributes, library) {
    let { cm_name, cm_id } = attributes.causal_model;
    if (library === "dowhy" || library === "econml" || library === "causalml") {
        console.log("connecting causal analysis w/ uuid: " + attributes.ca_uuid + " to causal model " + cm_id + " " + cm_name);
        //match causal model 
        let ca_insert_statement = "match\n";
        ca_insert_statement += "$causal_model isa causal_model, has nrid \"" + cm_id + "\";\n";
        ca_insert_statement += "$causal_analysis isa ca_" + library + ", has ca_uuid \"" + attributes.ca_uuid + "\";\n";
        ca_insert_statement += "insert\n";
        ca_insert_statement += "$causal_model(describes: $causal_analysis);\n";
        return ca_insert_statement;
    }
    return ""
}

