let session_types = {
    "DATA": SessionType.DATA,
    "SCHEMA": SessionType.READ,
}
let transaction_types = {
    "READ": TransactionType.READ,
    "WRITE": TransactionType.WRITE
}
/**
 * 
 * @param {obj} {
 *  {string} db: name of the typedb database we wish to query{
 *  {string} query :  statement to execute
 *  {string} query_type :  type of query [match, update, delete]
 *  {string} session_type : read / write
 *  {string}
 * }
 */
async function execute_query(opts) {
    let query_result = ""
    try {
        console.log("client ", client)
        if (client === "") {
            await create_client(uri)
        }
        if (client.isOpen()) {
            console.log("CLIENT IS OPEN")
        }
        console.log("db: ", opts.db)
        if (opts.db) {
            console.log("database ", database)
            console.log(database !== opts.db)
            if (database !== opts.db) {
                console.log("@execute_query: current database is not the same for query ")
                await set_database(opts.db)
            }
        }
        console.log("client is still open ? ", await client.isOpen())
        console.log(await client.databases)
        let ds = await list_databases()
        console.log("Ds", ds)

        console.log(Object.keys(client.databases))
        console.log("here")
        console.log(await client.databases.contains(opts.db))
        console.log("here 2")
        if (await client.databases.contains(opts.db)) {
            console.log("database exists")
            if (opts.session_type) {
                if (session === "") {
                    await create_session(opts.session_type)
                }
                // make sure session open is of same type else close and open right type
                else if (session.isOpen()) {
                    if (session.type !== session_types[opts.session_type]) {
                        await close_session()
                        await create_session(opts.session_type)
                    }
                }
                else {
                    await create_session(opts.session_type)
                }
            }
            if (session.isOpen()) {
                await create_transaction(opts.transaction_type)
                if (opts.transaction_type === "READ") {
                    console.log("transaction is open: ", await transaction.isOpen())
                    if (transaction.isOpen()) {
                        if (opts.query_type === "match") {
                            console.log("trnasacgtion is still open ", transaction.isOpen())
                            query_result = await transaction.query.match(opts.query).collect()
                            await close_transaction(opts.transaction_type)
                        }
                    }
                }
            }
        }
        console.log("@ execute_query result ", query_result)
        return query_result
    } catch (exception) {
        console.log("EXCEPTION AT TYPEDB ")
        console.log(exception)
        throw exception
    }
}

